using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using EternalSteam;using EternalSteam.OpenWorld;using EternalSteam.Railway;using Newtonsoft.Json.Linq;
public static class VerifyHud07Legacy{
const string Root="Docs/Measurements/2026-10-02-hud-07/editor/";static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
public static string Main(){if(!Application.isPlaying||!(Environment.GetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT")??"").Contains("hud-07"))throw new Exception("Isolated Play required");var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();var c=s.Content;var n=c.Railway.Network;var r=n.Routes.Single();Check(!r.train.segmentPaid,"Stationary required");var origin=n.Stations.OrderBy(b=>b.Cell.x).First().Cell;var owner=n.Stations.OrderBy(b=>b.Cell.x).First().OwnerBaseId;var input=s.GetComponent<OpenWorldInput>();var cells=new List<Vector2Int>();for(int y=1;y<=4;y++)cells.Add(new Vector2Int(8,y));for(int x=7;x>=-1;x--)cells.Add(new Vector2Int(x,4));for(int y=3;y>=0;y--)cells.Add(new Vector2Int(-1,y));foreach(var cell in cells){c.Bases.Select(owner);input.BeginEditing();Check(input.Edits.AddContent(s.RailwayHud.Track,c.GroundWorld.Grid.Center(cell+origin,Vector2Int.one),WorldGridGeometry.Rotation*Vector3.forward,out var why),why);var result=input.Edits.Confirm();Check(result.Success,result.Message);input.Cancel();}c.Railway.Refresh();var snapshot=n.Capture();var old=snapshot.routes.Single();old.mode=RailRouteMode.LegacyCycle;old.train.reverse=false;foreach(var stop in old.stops){stop.arrival=0;stop.departure=1;}Check(n.ValidateDraft(old.stops,old.id,out var legs,out var error),error);old.legs=legs;n.Restore(snapshot);
var v=s.RailwayHud.GetComponent<RailwayOverview>();var e=v.Editor;var h=v.Railway;v.Execute("open");v.Apply();v.Rows[0].onClick.Invoke();v.Execute("edit");e.SelectPage(1);
void Click(string cmd){v.Apply();var b=e.Bindings.Single(b=>b.Command==cmd).Button;Check(b.gameObject.activeInHierarchy&&b.interactable,"Legacy visible enabled "+cmd);b.onClick.Invoke();v.Apply();}
foreach(var cmd in new[]{"arrival","departure","map-arrival","map-departure","open-loop"})Check(e.Bindings.Single(b=>b.Command==cmd).Button.gameObject.activeInHierarchy,"Legacy access "+cmd);Click("open-loop");Check(!h.CanExecute("validate",out _),"Open cycle invalid");Click("close-loop");Click("map-arrival");h.Execute("port:1");v.Apply();Check(h.DraftIssues.Count>0&&h.DraftIssue!=null,"Port error surfaced");Check(e.Description.text.Contains(h.DraftIssue.Message),"Selected issue detail");Click("issue:0");Check(h.SelectedDraftStationId==h.DraftIssue.StationId,"Error selects station");Click("map-arrival");h.Execute("port:0");v.Apply();Check(h.DraftIssues.Count==0,"Port correction clears error");Click("validate");Check(e.Current==RailwayEditorPanel.Screen.Confirm,"Legacy confirmation");Click("back-edit");e.SelectPage(1);Click("arrival");File.WriteAllText(Root+"legacy-result.json",new JObject{{"result","PASS"},{"actualReturnTracks",true},{"legacyControlAccess",true},{"openClosedCycle",true},{"mapPortPick",true},{"errorSelectionAndCorrection",true},{"confirmation",true}}.ToString());return "PASS legacy controls, error selection and corrected cycle confirmation; error draft left for resolution review";}}
